**Gates before launch.** First, I check that pwd, the git remote, and the branch match this repo. I check that spe/predictions/r04.yaml and spe/plans/r04.md are in a commit and that no round 4 results exist yet. That proves the predictions came before the data. Next, I diff the script against the approved plan. It must use configs B and C2 only, 50 tickets, 5 trials, an Opus judge, and the $40 cap. I run grade.py on answers.json scored against itself and expect 100%. Then I run it on a copy with two labels changed on purpose and expect a lower score. I also confirm that answers.json has the same 50 ticket IDs as the ticket set. I compare the trial prompt framing with spe/evals/harness/r03-workflow.js so the only change between rounds is the config. Then I do the cost math. The run makes 2 x 50 x 5 = 500 trial calls and 500 judge calls, so 1,000 calls in total. The script cannot see dollars, so it caps the number of calls through `args.maxCalls`. I set maxCalls from $40 divided by R3's measured cost per call. If 1,000 calls will not fit under $40, I stop and ask you. I do not cut tickets or trials on my own. After that, I launch once with `smoke: true`, which makes 4 calls that count toward the cap. Last, I commit the script locally before the full run. The commit has no Claude attribution. The script returns raw outputs and judge scores. I save that JSON under spe/evals/ and run grade.py on it afterward. The script does no category or priority scoring itself, so grade.py stays the only code grader.

```js
export const meta = {
  name: 'spe-r04-triage-eval',
  description: 'SPE round 4. Configs B and C2 on 50 tickets with 5 trials per cell. An Opus judge scores reply tone with judge.md. grade.py scores label.category and label.priority after the run.',
  phases: [
    { title: 'Check inputs' },
    { title: 'Run trials' },
    { title: 'Judge tone' },
    { title: 'Summarize' },
  ],
}

// Expected args (the orchestrator reads the files before launch, because the script has no filesystem access):
// {
//   configs: { B: { prompt, tools: [...] }, C2: { prompt, tools: [...] } },
//   tickets: [{ id, subject, body }],   // all 50
//   judgeRubric: '<full text of spe/evals/graders/judge.md>',
//   trials: 5,
//   model: 'opus',          // model under test, same as R3 unless the plan says otherwise
//   judgeModel: 'opus',
//   maxCalls: <floor($40 / measured cost per call)>,
//   batchSize: 20,
//   smoke: false,
// }

const CONFIG_IDS = ['B', 'C2']
const EXPECTED_TICKETS = 50
const EXPECTED_TRIALS = 5
const PROMPT_LINES = 12
const TOOL_COUNTS = { B: 6, C2: 4 } // C2 is 3 tools plus check_status

const TRIAL_SCHEMA = {
  type: 'object',
  properties: {
    tool_calls: {
      type: 'array',
      items: {
        type: 'object',
        properties: { name: { type: 'string' }, arguments: { type: 'object' } },
        required: ['name'],
      },
    },
    label: {
      type: 'object',
      properties: { category: { type: 'string' }, priority: { type: 'string' } },
      required: ['category', 'priority'],
    },
    reply: { type: 'string' },
  },
  required: ['tool_calls', 'label', 'reply'],
}

const JUDGE_SCHEMA = {
  type: 'object',
  properties: { score: { type: 'number' }, rationale: { type: 'string' } },
  required: ['score', 'rationale'],
}

// ---------- Check inputs ----------
phase('Check inputs')

const cfgKeys = Object.keys(args.configs || {}).sort()
if (cfgKeys.join(',') !== CONFIG_IDS.join(',')) {
  throw new Error(`configs must be exactly B and C2. Got: ${cfgKeys.join(', ') || 'none'}`)
}
for (const id of CONFIG_IDS) {
  const c = args.configs[id]
  if (!c || typeof c.prompt !== 'string' || !Array.isArray(c.tools)) {
    throw new Error(`config ${id} needs a prompt string and a tools array`)
  }
  const lines = c.prompt.trim().split('\n').length
  if (lines !== PROMPT_LINES) throw new Error(`config ${id} prompt has ${lines} lines. The plan says ${PROMPT_LINES}.`)
  if (c.tools.length !== TOOL_COUNTS[id]) {
    throw new Error(`config ${id} has ${c.tools.length} tools. The plan says ${TOOL_COUNTS[id]}.`)
  }
}
if (!args.configs.C2.tools.some(t => t && t.name === 'check_status')) {
  throw new Error('config C2 must include a separate check_status tool')
}

const allTickets = args.tickets || []
if (allTickets.length !== EXPECTED_TICKETS) {
  throw new Error(`expected ${EXPECTED_TICKETS} tickets. Got ${allTickets.length}.`)
}
const ids = new Set(allTickets.map(t => t.id))
if (ids.size !== allTickets.length) throw new Error('ticket ids are not unique')
if (args.trials !== EXPECTED_TRIALS) throw new Error(`trials must be ${EXPECTED_TRIALS}. Got ${args.trials}.`)
if (typeof args.judgeRubric !== 'string' || args.judgeRubric.trim().length === 0) {
  throw new Error('judgeRubric is empty. Pass the text of spe/evals/graders/judge.md.')
}
if (!Number.isInteger(args.maxCalls) || args.maxCalls <= 0) {
  throw new Error('maxCalls must be a positive integer derived from the $40 cap')
}

const tickets = args.smoke ? allTickets.slice(0, 1) : allTickets
const trials = args.smoke ? 1 : args.trials
const model = args.model || 'opus'
const judgeModel = args.judgeModel || 'opus'
const batchSize = args.batchSize || 20
const needed = tickets.length * trials * CONFIG_IDS.length * 2

if (needed > args.maxCalls) {
  throw new Error(`run needs ${needed} calls but maxCalls is ${args.maxCalls}. Stop and ask. Do not shrink the run.`)
}
log(`r04: ${tickets.length} tickets x ${trials} trials x ${CONFIG_IDS.length} configs. ${needed} calls planned. Cap is ${args.maxCalls}.${args.smoke ? ' SMOKE RUN.' : ''}`)

// ---------- Budget guard ----------
let calls = 0
let halted = false

async function budgeted(prompt, opts) {
  if (calls >= args.maxCalls) {
    if (!halted) log(`call cap of ${args.maxCalls} reached. Remaining work is skipped.`)
    halted = true
    return null
  }
  calls++
  try {
    return await agent(prompt, opts)
  } catch (e) {
    log(`agent failed (${opts.label}): ${e && e.message ? e.message : e}`)
    return null
  }
}

async function inBatches(thunks) {
  const out = []
  for (let i = 0; i < thunks.length; i += batchSize) {
    const res = await parallel(thunks.slice(i, i + batchSize))
    out.push(...res)
    log(`batch done: ${Math.min(i + batchSize, thunks.length)} of ${thunks.length}. Calls so far: ${calls}.`)
  }
  return out
}

// ---------- Prompts ----------
function trialPrompt(cfg, ticket) {
  return [
    'You are the support triage agent under test.',
    'Do not use any tools. Do not read, search, or write any files. Work only from the text below.',
    '',
    '## System prompt',
    cfg.prompt,
    '',
    '## Tools you have',
    'These tools are simulated. List each call you would make in tool_calls, in order, with its arguments.',
    JSON.stringify(cfg.tools, null, 2),
    '',
    '## Ticket',
    `ID: ${ticket.id}`,
    `Subject: ${ticket.subject}`,
    '',
    ticket.body,
    '',
    'Return the label with its category and priority, and the reply you would send to the customer.',
  ].join('\n')
}

function judgePrompt(ticket, reply) {
  return [
    'You are grading the tone of a customer support reply.',
    'Do not use any tools. Do not read, search, or write any files.',
    'You do not know which configuration wrote this reply. Do not guess.',
    '',
    '## Rubric',
    args.judgeRubric,
    '',
    '## Ticket',
    `Subject: ${ticket.subject}`,
    '',
    ticket.body,
    '',
    '## Reply to grade',
    reply,
    '',
    'Return the score the rubric defines and a short rationale.',
  ].join('\n')
}

// ---------- Run trials ----------
phase('Run trials')

const jobs = []
for (const ticket of tickets) {
  for (let trial = 1; trial <= trials; trial++) {
    for (const configId of CONFIG_IDS) {
      jobs.push({ ticket, trial, configId })
    }
  }
}

const trialOutputs = await inBatches(jobs.map(j => () =>
  budgeted(trialPrompt(args.configs[j.configId], j.ticket), {
    label: `trial ${j.configId} ${j.ticket.id} t${j.trial}`,
    phase: 'Run trials',
    schema: TRIAL_SCHEMA,
    model,
  })
))

const results = jobs.map((j, i) => {
  const out = trialOutputs[i]
  const ok = !!(out && out.label && typeof out.reply === 'string')
  return {
    ticketId: j.ticket.id,
    config: j.configId,
    trial: j.trial,
    ok,
    label: ok ? out.label : null,
    reply: ok ? out.reply : null,
    toolCalls: ok ? out.tool_calls : null,
    judge: null,
  }
})

// ---------- Judge tone ----------
phase('Judge tone')

const toJudge = results
  .map((r, i) => ({ r, ticket: jobs[i].ticket }))
  .filter(x => x.r.ok)

const judgeOutputs = await inBatches(toJudge.map(x => () =>
  budgeted(judgePrompt(x.ticket, x.r.reply), {
    label: `judge ${x.r.ticketId} #${x.r.config === 'B' ? 'a' : 'b'}${x.r.trial}`,
    phase: 'Judge tone',
    schema: JUDGE_SCHEMA,
    model: judgeModel,
  })
))

toJudge.forEach((x, i) => {
  const j = judgeOutputs[i]
  x.r.judge = j && typeof j.score === 'number' ? { score: j.score, rationale: j.rationale } : null
})

// ---------- Summarize ----------
phase('Summarize')

const summary = {}
for (const id of CONFIG_IDS) {
  const rows = results.filter(r => r.config === id)
  const scored = rows.filter(r => r.judge)
  summary[id] = {
    trials: rows.length,
    failedTrials: rows.filter(r => !r.ok).length,
    judged: scored.length,
    meanTone: scored.length ? scored.reduce((s, r) => s + r.judge.score, 0) / scored.length : null,
  }
}

log(`calls used: ${calls} of ${args.maxCalls}. Halted: ${halted}.`)
for (const id of CONFIG_IDS) {
  const s = summary[id]
  log(`${id}: ${s.trials} trials, ${s.failedTrials} failed, ${s.judged} judged, mean tone ${s.meanTone === null ? 'n/a' : s.meanTone.toFixed(2)}`)
}
log('Next step: save this output and run spe/evals/graders/grade.py against spe/evals/tasks/answers.json for category and priority.')

return {
  round: 'r04',
  plan: 'spe/plans/r04.md',
  predictions: 'spe/predictions/r04.yaml',
  smoke: !!args.smoke,
  model,
  judgeModel,
  calls,
  maxCalls: args.maxCalls,
  halted,
  summary,
  results,
}
```

